local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local M={}
for i=1,#B do M[B:sub(i,i)]=i-1 end
local function b64(d)
    d=d:gsub("[^"..B.."=]","")
    local o,i={},1
    while i<=#d do
        local a,b,c,e=d:sub(i,i),d:sub(i+1,i+1),d:sub(i+2,i+2),d:sub(i+3,i+3)
        local n1,n2=M[a] or 0,M[b] or 0
        local n3,n4=M[c],M[e]
